/// Live outcome of one compensation operation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct GroupCompensationStatus {
    pub operation_id: String,
