export interface FakeBehavior {
  /** Next N setter commands end in the selected status. */
  failNext: number;
  /** A definite provider failure or an ambiguous remote outcome. */
  failureKind: 'provider_unavailable' | 'provider_rejected' | 'outcome_unknown';
  /** When true, operations stay in `applying` until `release()`. */
  hold: boolean;
  /** When true, operations stay in `queued` (unclaimed by the worker) until `release()`. */
  holdQueued: boolean;
  /** When true, `undoOperation` calls stay pending until `release()`. */
  holdUndo: boolean;
  /** Hold the synthetic OAuth-upgrade completion until releaseUpgrade(). */
  holdUpgrade: boolean;
}

/** Simulated core account/sync state; mutated only through `setAccount`. */
export interface FakeAccountState {
  mode: MailMode;
  connection: ConnectionState;
  /** Address reported in `AccountInfo`; `null` means core has no account yet. */
  emailAddress: string | null;
  syncState: SyncState;
  lastSyncedAt: string | null;
  syncError: MailError | null;
  cachedConversations: number;
  initialSyncComplete: boolean;
  /** Core's discovery cap (0 = no disclosed cap, e.g. fixture mode). */
  coverageLimit: number;
  mutationAccess: MutationAccess;
}

export interface FakeControls {
  behavior: FakeBehavior;
  /** Lets all in-flight fake-provider work finish (await until quiet). */
  flush(): Promise<void>;
  /** Releases held operations. */
  release(): void;
  /** Direct read of internal activity, for assertions. */
  activity(): OperationSummary[];
  /** Number of active change listeners (teardown assertions). */
  listenerCount(): number;
  draftListenerCount(): number;
  closeListenerCount(): number;
  /** Emits one synthetic, non-durable close request without closing a browser window. */
  requestAppClose(): AppCloseRequest;
  pendingAppClose(): AppCloseRequest | null;
  completedCloseCount(): number;
  /** Current simulated account/sync state. */
  accountState(): Readonly<FakeAccountState>;
  /** Patches the simulated account/sync state and notifies change listeners. */
  setAccount(patch: Partial<FakeAccountState>): void;
  /** Holds the next N `getAccountStatus` calls until `releaseStatus()`. */
  holdNextStatus(count?: number): void;
  /** Releases all held `getAccountStatus` calls. */
  releaseStatus(): void;
  /** Next `getAccountStatus` rejects with this error (once). */
  failNextStatus(error?: MailError): void;
  /** Next `connectAccount` rejects after flipping back to the prior connection. */
  failNextConnect(error?: MailError): void;
  /** Next `disconnectAccount` rejects and keeps the current state. */
  failNextDisconnect(error?: MailError): void;
  /** Next `requestSync` ends in `sync: 'error'` with this error. */
  failNextSync(error?: MailError): void;
  /** Fails the next synthetic permission upgrade without changing prior access. */
  failNextEnable(error?: MailError): void;
  /** Releases a held synthetic permission upgrade. */
  releaseUpgrade(): void;
  /** Makes the next synthetic cancellation fail. */
  failNextCancelUpgrade(error?: MailError): void;
  /** Adds an incoming message to test immutable operation target snapshots. */
  addMessage(conversationId: string, read?: boolean, from?: Address): void;
  /** Makes read facts unknown for a synthetic conversation. */
  markReadUnknown(conversationId: string): void;
  /** Marks an Activity-openable local recovery copy with a synthetic save time. */
  markRetainedSnapshot(conversationId: string, savedAt: string): void;
  /** Synthetic conversation-level aggregate only; not provider mutation or per-message storage. */
  markTriage(conversationId: string, membership: 'trash' | 'spam' | null): void;
  /** Flags a seeded conversation with Gmail plain-text limitations. */
  markUnsupported(conversationId: string, unsupportedReason: string, contextComplete?: boolean): void;
}

export interface BrowserFake extends MailClient {
  controls: FakeControls;
  /** Always true; the UI surfaces this to force the memory-only disclosure. */
  readonly memoryOnly: true;
}

const ACCOUNT_ID = 'fixture-account';
const CONVERSATION_COUNT = 18;

function pendingOperationId(conv: FakeConversation): string | null {
  for (let i = conv.ops.length - 1; i >= 0; i -= 1) {
    const op = conv.ops[i];
    if (op && (op.status === 'queued' || op.status === 'applying' || op.status === 'outcome_unknown')) return op.id;
  }
  return null;
}

const UNDO_WINDOW_MS = 10_000;

function toOperationSummary(op: InternalOperation, accountId: string, undoableUntil?: string): OperationSummary {
  return {
    id: op.id,
    conversation: { accountId, conversationId: op.conversationId },
    requestedArchived: op.kind === 'star' ? false : op.requestedArchived,
    ...(op.kind === 'star' ? { requestedStarred: op.requestedArchived } : {}),
    status: op.status,
    failure: op.failure,
    kind: op.kind,
    ...(op.requestedRead === undefined ? {} : { requestedRead: op.requestedRead }),
    ...(op.lastError === undefined ? {} : { lastError: op.lastError }),
    ...(op.undoOf === undefined ? {} : { undoOf: op.undoOf }),
    ...(op.retryOf === undefined ? {} : { retryOf: op.retryOf }),
    ...(op.groupId === undefined ? {} : { groupId: op.groupId }),
    ...(undoableUntil === undefined ? {} : { undoableUntil }),
  };
}

/** Immutable fixture identity; never used to select a native profile or credentials. */
export interface FixtureIdentity { accountId: string; emailAddress: string }

export function createBrowserFakeMailClient(
  now: () => string = () => new Date().toISOString(),
  identity: FixtureIdentity = { accountId: ACCOUNT_ID, emailAddress: FIXTURE_MAILBOX },
): BrowserFake {
  // Capture values rather than retaining a caller-mutable identity object.
  const fixtureId = identity.accountId;
  const fixtureMailbox = identity.emailAddress;
  let savedSplit: SavedSplit | null = null;
  const ME = addr('You', fixtureMailbox);
  const conversations = seedConversations(fixtureId, fixtureMailbox);
  const listeners = new Set<() => void>();
  const draftListeners = new Set<() => void>();
  const closeListeners = new Set<(request: AppCloseRequest) => void>();
  const drafts = new Map<string, Draft>();
  const draftReceipts = new Map<string, { fingerprint: string; receipt: DraftReceipt | DraftDeleteReceipt }>();
  let draftCounter = 0;
  let closeCounter = 0;
  let pendingClose: AppCloseRequest | null = null;
  let completedCloses = 0;
  const receiptsByRequest = new Map<string, { fingerprint: string; receipt: OperationReceipt | UndoReceipt }>();
  const groups: InternalGroup[] = [];
  const groupReceiptsByRequest = new Map<string, { fingerprint: string; receipt: OperationGroupReceipt }>();
  const groupUndoReceiptsByRequest = new Map<string, { fingerprint: string; receipt: GroupUndoReceipt }>();
  const reminders = new Map<string, Reminder>();
  const reminderReceipts = new Map<string, { fingerprint: string; reminder: Reminder }>();
  const reminderSourceInventories = new Map<string, Set<string>>();
  let groupCounter = 0;
  /** Shared top-level action-order identity across singles, group children and groups. */
  let actionSeqCounter = 0;
  const behavior: FakeBehavior = { failNext: 0, failureKind: 'provider_rejected', hold: false, holdQueued: false, holdUpgrade: false, holdUndo: false };

  let opCounter = 0;
  let inFlight = 0;
  let holdReleased = false;
  const holdWaiters: Array<() => void> = [];
  const undoWaiters: Array<() => void> = [];

  // Slice 02 account simulation. Fixture mode is the default so the Slice 01 preview
  // and its tests keep working unchanged.
  const account: FakeAccountState = {
    mode: 'fixture',
    connection: 'connected',
    emailAddress: fixtureMailbox,
    syncState: 'idle',
    lastSyncedAt: null,
    syncError: null,
    cachedConversations: CONVERSATION_COUNT,
    initialSyncComplete: true,
    coverageLimit: 0,
    mutationAccess: 'read_only',
  };
  // Core clears local cache data on disconnect; the fake mirrors that with a flag.
  let cacheCleared = false;
  const destinationCatalogs = new Map<string, import('./client').DestinationCatalog>();
  const destinationPages = new Map<string, import('./client').DestinationPage>();
  let heldStatusCalls = 0;
  const statusHoldWaiters: Array<() => void> = [];
  let failStatus: MailError | null = null;
  let failConnect: MailError | null = null;
  let failDisconnect: MailError | null = null;
  let failSync: MailError | null = null;
  let failEnable: MailError | null = null;
  let failCancelUpgrade: MailError | null = null;
  let upgradeGeneration = 0;
  let upgradeReleased = false;
  const upgradeWaiters: Array<() => void> = [];

  const notify = (): void => {
    for (const listener of listeners) listener();
  };

  const notifyDrafts = (): void => {
    for (const listener of draftListeners) listener();
  };

  const activeDraftAccountId = (): string | null => accountStatus().account?.accountId ?? null;

  const draftSummary = (draft: Draft): DraftSummary => ({
    ref: { ...draft.ref }, revision: draft.revision, updatedAt: draft.updatedAt,
    subject: draft.content.subject, to: draft.content.to, source: snapshotCopy(draft.source),
  });

  function validateDraftContent(content: DraftContent): void {
    const limits: Array<[keyof DraftContent, number]> = [['to', 16 * 1024], ['cc', 16 * 1024], ['subject', 4 * 1024], ['bodyText', 1024 * 1024]];
    for (const [field, max] of limits) {
      if (new TextEncoder().encode(content[field]).length > max) {
        throw { kind: 'invalid_request', field } satisfies MailError;
      }
    }
  }

  function draftCommandFingerprint(kind: string, command: unknown): string {
    const serialized = JSON.stringify([kind, command]);
    let first = 2166136261;
    let second = 0x9e3779b9;
    for (let i = 0; i < serialized.length; i += 1) {
      const code = serialized.charCodeAt(i);
      first = Math.imul(first ^ code, 16777619);
      second = Math.imul(second ^ (code + i), 2246822519);
    }
    return `${serialized.length}:${first >>> 0}:${second >>> 0}`;
  }

  function validateDraftRequestId(requestId: string): void {
    if (!requestId || new TextEncoder().encode(requestId).length > 128) {
      throw { kind: 'invalid_request', field: 'requestId' } satisfies MailError;
    }
  }

  function existingDraftReceipt<T extends DraftReceipt | DraftDeleteReceipt>(accountId: string, requestId: string, fingerprint: string): T | null {
    validateDraftRequestId(requestId);
    const existing = draftReceipts.get(`${accountId}:${requestId}`);
    if (!existing) return null;
    if (existing.fingerprint !== fingerprint) throw { kind: 'request_id_conflict' } satisfies MailError;
    return snapshotCopy(existing.receipt) as T;
  }

  const settle = (): Promise<void> => Promise.resolve();

  function accountStatus(): AccountStatus {
    const cached = account.mode === 'gmail'
      ? (cacheCleared ? 0 : account.cachedConversations)
      : conversations.length;
    return {
      mode: account.mode,
      connection: account.connection,
      account: account.emailAddress
        ? {
            accountId: account.mode === 'gmail' ? 'gmail-account' : fixtureId,
            emailAddress: account.emailAddress,
          }
        : null,
      sync: {
        state: account.syncState,
        lastSyncedAt: account.lastSyncedAt,
        error: account.syncError ? { ...account.syncError } : null,
        cachedConversations: cached,
        initialSyncComplete: account.initialSyncComplete,
        coverageLimit: account.coverageLimit,
      },
      mutationAccess: account.mode === 'gmail' ? account.mutationAccess : 'read_only',
    };
  }

  const byId = (conversationId: string): FakeConversation | undefined =>
    cacheCleared || !accountStatus().account ? undefined :
      conversations.find((c) => c.ref.conversationId === conversationId && c.ref.accountId === accountStatus().account?.accountId);

  const allOps = (): Array<{ conv: FakeConversation; op: InternalOperation }> =>
    conversations.flatMap((conv) => conv.ops.map((op) => ({ conv, op })));

  /** Effective prior value of the operation's dimension per target, captured before it joins the overlay. */
  function effectivePriorValues(conv: FakeConversation, kind: MailboxOperationKind, messageIds: string[]): Record<string, boolean | null> {
    const inbox = effectiveInInbox(conv);
    const read = effectiveRead(conv);
    const values: Record<string, boolean | null> = {};
    for (let i = 0; i < conv.messages.length; i += 1) {
      const message = conv.messages[i];
      if (!message || !messageIds.includes(message.id)) continue;
      // Archive ops restore archived-ness (the inverse of INBOX membership);
      // read ops restore read-ness, which can be an unknown fact.
      values[message.id] = kind === 'star' ? effectiveStars(conv)[i] ?? null : kind === 'archive' ? !inbox[i] : read[i] ?? null;
    }
    return values;
  }

  /** §3.2 rules 2–7 (rule 1 holds by construction in the single-account fake). */
  function undoBlocker(op: InternalOperation): MailError | null {
    if (op.undoOf !== undefined) return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    // Group children are part of their group's top-level action: they are never
    // individually undoable (docs/ux-05-safe-bulk-processing.md §5).
    if (op.groupId !== undefined) return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    if (Date.parse(now()) >= Date.parse(op.acceptedAt) + UNDO_WINDOW_MS) {
      return { kind: 'undo_unavailable', reason: 'expired' } satisfies MailError;
    }
    if (supersededByNewerAction(op.seq)) {
      return { kind: 'undo_unavailable', reason: 'superseded' } satisfies MailError;
    }
    if (allOps().some((entry) => entry.op.undoOf === op.id)) {
      return { kind: 'undo_unavailable', reason: 'already_undone' } satisfies MailError;
    }
    if (op.status === 'outcome_unknown') return { kind: 'undo_unavailable', reason: 'uncertain' } satisfies MailError;
    if (op.status !== 'queued' && op.status !== 'applying' && op.status !== 'confirmed') {
      // A cancelled op was already undone in place; a re-undo reports
      // already_undone, matching Rust's rule ordering.
      if (op.status === 'cancelled') return { kind: 'undo_unavailable', reason: 'already_undone' } satisfies MailError;
      return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    }
    if (op.messageIds.some((id) => op.priorValues[id] === undefined || op.priorValues[id] === null)) {
      return { kind: 'undo_unavailable', reason: 'unknown_prior' } satisfies MailError;
    }
    return null;
  }

  /** `undoableUntil` is present only while every undo rule still holds at query time. */
  function summarizeOperation(op: InternalOperation, accountId: string): OperationSummary {
    return toOperationSummary(
      op,
      accountId,
      undoBlocker(op) ? undefined : new Date(Date.parse(op.acceptedAt) + UNDO_WINDOW_MS).toISOString(),
    );
  }

  /** A newer standalone single or a newer action-bearing group supersedes `seq`. */
  function supersededByNewerAction(seq: number): boolean {
    return allOps().some((entry) => entry.op.undoOf === undefined && entry.op.groupId === undefined && entry.op.seq > seq)
      || groups.some((g) => g.acceptedChildren > 0 && g.seq > seq);
  }

  /** One group's undo window: latest top-level action, 10 s from group
   * acceptance, and at least one member still eligible (an all-ineligible
   * group offers no enabled Undo, §5). */
  function groupUndoBlocker(group: InternalGroup): MailError | null {
    if (group.undone) return { kind: 'undo_unavailable', reason: 'already_undone' } satisfies MailError;
    if (group.acceptedChildren === 0) return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    if (Date.parse(now()) >= Date.parse(group.acceptedAt) + UNDO_WINDOW_MS) {
      return { kind: 'undo_unavailable', reason: 'expired' } satisfies MailError;
    }
    if (supersededByNewerAction(group.seq)) return { kind: 'undo_unavailable', reason: 'superseded' } satisfies MailError;
    // Per-member eligibility mirrors Rust: some accepted child must be live
    // (queued/applying/confirmed), not already compensated, with known priors.
    const anyEligible = group.members.some((member) => {
      if (member.operationId === null) return false;
      const op = allOps().find((entry) => entry.op.id === member.operationId)?.op;
      if (!op) return false;
      const live = op.status === 'queued' || op.status === 'applying' || op.status === 'confirmed';
      const knownPriors = op.messageIds.every((id) => op.priorValues[id] !== undefined && op.priorValues[id] !== null);
      const notUndone = !allOps().some((entry) => entry.op.undoOf === op.id);
      return live && knownPriors && notUndone;
    });
    if (!anyEligible) return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    return null;
  }

  function memberStatusView(member: GroupMemberReceipt): GroupMemberStatusView {
    const op = member.operationId
      ? allOps().find((entry) => entry.op.id === member.operationId)?.op ?? null
      : null;
    return {
      ordinal: member.ordinal,
      conversation: { ...member.conversation },
      operationId: member.operationId,
      status: op ? op.status : 'rejected',
      failure: op ? op.failure : null,
      rejection: member.rejection,
    };
  }

  function groupStatus(group: InternalGroup): OperationGroupStatus {
    const blocker = groupUndoBlocker(group);
    return {
      group: snapshotCopy(groupReceipt(group)),
      members: group.members.map((member) => memberStatusView(member)),
      undo: blocker
        ? { available: false, reason: blocker.kind === 'undo_unavailable' ? blocker.reason : null, undoableUntil: null }
        : { available: true, reason: null, undoableUntil: new Date(Date.parse(group.acceptedAt) + UNDO_WINDOW_MS).toISOString() },
      ...(group.undone && group.undoReceipt ? { undoReceipt: persistedUndoRecord(group) } : {}),
    };
  }

  /** Persisted group-Undo record with CURRENT compensation outcomes (§4.2/§5);
   * mirrors Rust's `OperationGroupStatus.undoReceipt`. */
  function persistedUndoRecord(group: InternalGroup): OperationGroupStatus['undoReceipt'] {
    const receipt = group.undoReceipt;
    if (!receipt) return undefined;
    return {
      requestId: receipt.requestId,
      acceptedAt: receipt.acceptedAt,
      members: receipt.members.map((member) => ({
        ordinal: member.ordinal,
        decision: member.decision,
        compensations: member.operationIds.map((operationId) => {
          const op = allOps().find((entry) => entry.op.id === operationId)?.op;
          return {
            operationId,
            status: op?.status ?? 'outcome_unknown',
            failure: op?.failure ?? null,
          };
        }),
      })),
    };
  }

  function groupReceipt(group: InternalGroup): OperationGroupReceipt {
    return {
      groupId: group.groupId,
      requestId: group.requestId,
      accountId: group.accountId,
      kind: group.kind,
      ...(group.kind === 'star' ? {requestedStarred:group.requestedArchived} : {}),
      ...(group.kind === 'star' || group.requestedArchived === undefined ? {} : { requestedArchived: group.requestedArchived }),
      ...(group.requestedRead === undefined ? {} : { requestedRead: group.requestedRead }),
      acceptedAt: group.acceptedAt,
      members: snapshotCopy(group.members),
    };
  }

  function groupSummary(group: InternalGroup): OperationGroupPage['groups'][number] {
    return {
      groupId: group.groupId,
      requestId: group.requestId,
      kind: group.kind,
      ...(group.kind === 'star' ? {requestedStarred:group.requestedArchived} : {}),
      ...(group.kind === 'star' || group.requestedArchived === undefined ? {} : { requestedArchived: group.requestedArchived }),
      ...(group.requestedRead === undefined ? {} : { requestedRead: group.requestedRead }),
      acceptedAt: group.acceptedAt,
      members: group.members.map((member) => ({ ...member.conversation })),
      undone: group.undone,
    };
  }

  /**
   * Shared group acceptance for archive and read groups (UX-05 §4.1 in-memory):
   * structural validation, idempotent receipt lookup, per-member acceptance with
   * typed rejections, one durable receipt. All-rejected valid requests still get
   * an idempotent receipt with zero child operations and consume no undo slot.
   */
  function acceptGroup(
    command: { accountId: string; members: ConversationRef[]; requestId: string },
    kind: MailboxOperationKind,
    requested: { archived?: boolean; read?: boolean },
  ): OperationGroupReceipt {
    requireMutationAccess(kind);
    if (!command.accountId || command.accountId !== accountStatus().account?.accountId) {
      throw { kind: 'invalid_request', field: 'accountId' } satisfies MailError;
    }
    if (!Array.isArray(command.members) || command.members.length < 1 || command.members.length > OPERATION_GROUP_MAX_MEMBERS) {
      throw { kind: 'invalid_request', field: 'members' } satisfies MailError;
    }
    for (const member of command.members) {
      if (!member || typeof member.accountId !== 'string' || !member.accountId
        || typeof member.conversationId !== 'string' || !member.conversationId) {
        throw { kind: 'invalid_request', field: 'members' } satisfies MailError;
      }
    }
    // Cross-account members reject the whole request (no partial acceptance).
    if (command.members.some((member) => member.accountId !== command.accountId)) {
      throw { kind: 'invalid_request', field: 'members' } satisfies MailError;
    }
    const seen = new Set<string>();
    for (const member of command.members) {
      const key = `${member.accountId}:${member.conversationId}`;
      if (seen.has(key)) throw { kind: 'invalid_request', field: 'members' } satisfies MailError;
      seen.add(key);
    }
    const fingerprint = JSON.stringify([
      'operation-group', kind, command.accountId,
      command.members.map((member) => [member.accountId, member.conversationId]),
      requested.archived, requested.read,
    ]);
    const requestKey = `${command.accountId}:${command.requestId}`;
    const existing = groupReceiptsByRequest.get(requestKey);
    if (existing) {
      if (existing.fingerprint !== fingerprint) throw { kind: 'request_id_conflict' } satisfies MailError;
      return snapshotCopy(existing.receipt);
    }
    groupCounter += 1;
    const groupId = `grp-${String(groupCounter).padStart(4, '0')}`;
    const acceptedAt = now();
    const members: GroupMemberReceipt[] = [];
    for (let ordinal = 0; ordinal < command.members.length; ordinal += 1) {
      const ref = command.members[ordinal]!;
      const conv = byId(ref.conversationId);
      if (!conv || conv.ref.accountId !== command.accountId) {
        members.push({ ordinal, conversation: { ...ref }, operationId: null, rejection: 'conversation_missing' });
        continue;
      }
      // Mirrors core's existing 1000-messages-per-operation bound.
      if (conv.messages.length > 1000) {
        members.push({ ordinal, conversation: { ...ref }, operationId: null, rejection: 'target_bound_exceeded' });
        continue;
      }
      const child = enqueueOperation(
        conv,
        kind,
        requested.archived ?? false,
        requested.read,
        conv.messages.map((message) => message.id),
        `${command.requestId}:${ordinal}`,
        JSON.stringify(['group-child', command.requestId, ordinal]),
        { groupId, acceptedAt },
      );
      members.push({ ordinal, conversation: { accountId: ref.accountId, conversationId: ref.conversationId }, operationId: child.operationId, rejection: null });
    }
    const group: InternalGroup = {
      groupId,
      requestId: command.requestId,
      accountId: command.accountId,
      kind,
      ...(requested.archived === undefined ? {} : { requestedArchived: requested.archived }),
      ...(requested.read === undefined ? {} : { requestedRead: requested.read }),
      acceptedAt,
      seq: ++actionSeqCounter,
      members,
      acceptedChildren: members.filter((member) => member.operationId !== null).length,
      undone: false,
    };
    groups.push(group);
    const receipt = groupReceipt(group);
    groupReceiptsByRequest.set(requestKey, { fingerprint, receipt: snapshotCopy(receipt) });
    notify();
    return snapshotCopy(receipt);
  }

  function snapshot(): InboxSnapshot {
    reconcileFakeReminders();
    // No account / cleared cache means no cached mail; core would return the same.
    const empty =
      cacheCleared ||
      (account.mode === 'gmail' && (account.connection === 'not_configured' || account.connection === 'disconnected'));
    const activity = empty
      ? []
      : conversations
          .flatMap((c) => c.ops.map((op) => summarizeOperation(op, c.ref.accountId)))
          .sort((a, b) => a.id.localeCompare(b.id));
    const rows = empty
      ? []
      : conversations
          .map((c) => ({ c, flags: effectiveInInbox(c) }))
          .filter((entry) => !entry.c.triage && entry.flags.some((f) => f)
            && (reminders.get(`${entry.c.ref.accountId}:${entry.c.ref.conversationId}`)?.phase !== 'pending'
              || entry.c.messages.some(message => !reminderSourceInventories.get(`${entry.c.ref.accountId}:${entry.c.ref.conversationId}`)?.has(message.id))))
          .map((entry) => summarize(entry.c, pendingOperationId(entry.c)))
          .sort((a, b) => b.lastMessageAt.localeCompare(a.lastMessageAt));
    return snapshotCopy({ conversations: rows, activity });
  }

  function reconcileFakeReminders(): void {
    const instant = Date.parse(now());
    for (const reminder of reminders.values()) {
      if (reminder.phase === 'pending' && reminder.dueAt && Date.parse(reminder.dueAt) <= instant) {
        const conv = byId(reminder.conversation.conversationId);
        if (reminder.condition === 'if_no_reply' && (!conv || conv.contextComplete === false || conv.retainedSnapshotAt || account.connection !== 'connected' || account.syncError || !account.initialSyncComplete)) continue;
        const sourceIds = reminderSourceInventories.get(`${reminder.conversation.accountId}:${reminder.conversation.conversationId}`) ?? new Set([reminder.sourceMessageId]);
        const primary = accountStatus().account?.emailAddress?.toLowerCase();
        const replied = reminder.condition === 'if_no_reply' && conv?.messages.some(message =>
          !sourceIds.has(message.id) && message.from.mailbox.toLowerCase() !== primary);
        reminder.phase = replied ? 'suppressed' : 'returned';
        reminder.revision += 1;
      }
    }
  }

  function failNotShown(): MailError {
    return { kind: 'not_found' };
  }

  function requireMutationAccess(kind: MailboxOperationKind): void {
    if ((kind === 'read' || kind === 'star') && account.mode !== 'gmail') throw { kind: 'read_only' } satisfies MailError;
    if (account.mode === 'gmail' && account.mutationAccess !== 'enabled') throw { kind: 'read_only' } satisfies MailError;
  }

  function existingReceipt<T = OperationReceipt>(requestId: string, fingerprint: string): T | null {
    const existing = receiptsByRequest.get(requestId);
    if (!existing) return null;
    if (existing.fingerprint !== fingerprint) throw { kind: 'request_id_conflict' } satisfies MailError;
    return snapshotCopy(existing.receipt) as T;
  }

  function enqueueOperation(
    conv: FakeConversation,
    kind: MailboxOperationKind,
    requestedArchived: boolean,
    requestedRead: boolean | undefined,
    messageIds: string[],
    requestId: string,
    fingerprint: string,
    options: { priorValues?: Record<string, boolean | null>; undoOf?: string; groupId?: string; acceptedAt?: string; retryOf?: string } = {},
  ): OperationReceipt {
    opCounter += 1;
    const operationId = `op-${String(opCounter).padStart(4, '0')}`;
    const acceptedAt = options.acceptedAt ?? now();
    const receipt: OperationReceipt = { operationId, acceptedAt };
    receiptsByRequest.set(requestId, { fingerprint, receipt });
    const op: InternalOperation = {
      id: operationId,
      conversationId: conv.ref.conversationId,
      kind,
      requestedArchived,
      ...(requestedRead === undefined ? {} : { requestedRead }),
      messageIds: [...messageIds],
      status: 'queued',
      failure: null,
      acceptedAt,
      seq: ++actionSeqCounter,
      // Per-message effective value of THIS operation's dimension at acceptance
      // (before this op joins the overlay); retries reuse the original's preimage.
      priorValues: options.priorValues
        ? { ...options.priorValues }
        : effectivePriorValues(conv, kind, messageIds),
      ...(options.undoOf === undefined ? {} : { undoOf: options.undoOf }),
      ...(options.retryOf === undefined ? {} : { retryOf: options.retryOf }),
      ...(options.groupId === undefined ? {} : { groupId: options.groupId }),
    };
    conv.ops.push(op);
    if (behavior.hold || behavior.holdQueued) holdReleased = false;
    notify();
    void runOperation(op).then(() => notify());
    return snapshotCopy(receipt);
  }

  async function runOperation(op: InternalOperation): Promise<vo

/** Simulated core account/sync state; mutated only through `setAccount`. */
export interface FakeAccountState {
  mode: MailMode;
  connection: ConnectionState;
  /** Address reported in `AccountInfo`; `null` means core has no account yet. */
  emailAddress: string | null;
  syncState: SyncState;
  lastSyncedAt: string | null;
  syncError: MailError | null;
  cachedConversations: number;
  initialSyncComplete: boolean;
  /** Core's discovery cap (0 = no disclosed cap, e.g. fixture mode). */
  coverageLimit: number;
  mutationAccess: MutationAccess;
}

export interface FakeControls {
  behavior: FakeBehavior;
  /** Lets all in-flight fake-provider work finish (await until quiet). */
  flush(): Promise<void>;
  /** Releases held operations. */
  release(): void;
  /** Direct read of internal activity, for assertions. */
  activity(): OperationSummary[];
  /** Number of active change listeners (teardown assertions). */
  listenerCount(): number;
  draftListenerCount(): number;
  closeListenerCount(): number;
  /** Emits one synthetic, non-durable close request without closing a browser window. */
  requestAppClose(): AppCloseRequest;
  pendingAppClose(): AppCloseRequest | null;
  completedCloseCount(): number;
  /** Current simulated account/sync state. */
  accountState(): Readonly<FakeAccountState>;
  /** Patches the simulated account/sync state and notifies change listeners. */
  setAccount(patch: Partial<FakeAccountState>): void;
  /** Holds the next N `getAccountStatus` calls until `releaseStatus()`. */
  holdNextStatus(count?: number): void;
  /** Releases all held `getAccountStatus` calls. */
  releaseStatus(): void;
  /** Next `getAccountStatus` rejects with this error (once). */
  failNextStatus(error?: MailError): void;
  /** Next `connectAccount` rejects after flipping back to the prior connection. */
  failNextConnect(error?: MailError): void;
  /** Next `disconnectAccount` rejects and keeps the current state. */
  failNextDisconnect(error?: MailError): void;
  /** Next `requestSync` ends in `sync: 'error'` with this error. */
  failNextSync(error?: MailError): void;
  /** Fails the next synthetic permission upgrade without changing prior access. */
  failNextEnable(error?: MailError): void;
  /** Releases a held synthetic permission upgrade. */
  releaseUpgrade(): void;
  /** Makes the next synthetic cancellation fail. */
  failNextCancelUpgrade(error?: MailError): void;
  /** Adds an incoming message to test immutable operation target snapshots. */
  addMessage(conversationId: string, read?: boolean, from?: Address): void;
  /** Makes read facts unknown for a synthetic conversation. */
  markReadUnknown(conversationId: string): void;
  /** Marks an Activity-openable local recovery copy with a synthetic save time. */
  markRetainedSnapshot(conversationId: string, savedAt: string): void;
  /** Synthetic conversation-level aggregate only; not provider mutation or per-message storage. */
  markTriage(conversationId: string, membership: 'trash' | 'spam' | null): void;
  /** Flags a seeded conversation with Gmail plain-text limitations. */
  markUnsupported(conversationId: string, unsupportedReason: string, contextComplete?: boolean): void;
}

export interface BrowserFake extends MailClient {
  controls: FakeControls;
  /** Always true; the UI surfaces this to force the memory-only disclosure. */
  readonly memoryOnly: true;
}

export function createBrowserFakeMailClient(
  now: () => string = () => new Date().toISOString(),
  identity: FixtureIdentity = { accountId: ACCOUNT_ID, emailAddress: FIXTURE_MAILBOX },
): BrowserFake {
  // Capture values rather than retaining a caller-mutable identity object.
  const fixtureId = identity.accountId;
  const fixtureMailbox = identity.emailAddress;
  let savedSplit: SavedSplit | null = null;
  const ME = addr('You', fixtureMailbox);
  const conversations = seedConversations(fixtureId, fixtureMailbox);
  const listeners = new Set<() => void>();
  const draftListeners = new Set<() => void>();
  const closeListeners = new Set<(request: AppCloseRequest) => void>();
  const drafts = new Map<string, Draft>();
  const draftReceipts = new Map<string, { fingerprint: string; receipt: DraftReceipt | DraftDeleteReceipt }>();
  let draftCounter = 0;
  let closeCounter = 0;
  let pendingClose: AppCloseRequest | null = null;
  let completedCloses = 0;
  const receiptsByRequest = new Map<string, { fingerprint: string; receipt: OperationReceipt | UndoReceipt }>();
  const groups: InternalGroup[] = [];
  const groupReceiptsByRequest = new Map<string, { fingerprint: string; receipt: OperationGroupReceipt }>();
  const groupUndoReceiptsByRequest = new Map<string, { fingerprint: string; receipt: GroupUndoReceipt }>();
  const reminders = new Map<string, Reminder>();
  const reminderReceipts = new Map<string, { fingerprint: string; reminder: Reminder }>();
  const reminderSourceInventories = new Map<string, Set<string>>();
  let groupCounter = 0;
  /** Shared top-level action-order identity across singles, group children and groups. */
  let actionSeqCounter = 0;
  const behavior: FakeBehavior = { failNext: 0, failureKind: 'provider_rejected', hold: false, holdQueued: false, holdUpgrade: false, holdUndo: false };

  let opCounter = 0;
  let inFlight = 0;
  let holdReleased = false;
  const holdWaiters: Array<() => void> = [];
  const undoWaiters: Array<() => void> = [];

  // Slice 02 account simulation. Fixture mode is the default so the Slice 01 preview
  // and its tests keep working unchanged.
  const account: FakeAccountState = {
    mode: 'fixture',
    connection: 'connected',
    emailAddress: fixtureMailbox,
    syncState: 'idle',
    lastSyncedAt: null,
    syncError: null,
    cachedConversations: CONVERSATION_COUNT,
    initialSyncComplete: true,
    coverageLimit: 0,
    mutationAccess: 'read_only',
  };
  // Core clears local cache data on disconnect; the fake mirrors that with a flag.
  let cacheCleared = false;
  const destinationCatalogs = new Map<string, import('./client').DestinationCatalog>();
  const destinationPages = new Map<string, import('./client').DestinationPage>();
  let heldStatusCalls = 0;
  const statusHoldWaiters: Array<() => void> = [];
  let failStatus: MailError | null = null;
  let failConnect: MailError | null = null;
  let failDisconnect: MailError | null = null;
  let failSync: MailError | null = null;
  let failEnable: MailError | null = null;
  let failCancelUpgrade: MailError | null = null;
  let upgradeGeneration = 0;
  let upgradeReleased = false;
  const upgradeWaiters: Array<() => void> = [];

  const notify = (): void => {
    for (const listener of listeners) listener();
  };

  const notifyDrafts = (): void => {
    for (const listener of draftListeners) listener();
  };

  const activeDraftAccountId = (): string | null => accountStatus().account?.accountId ?? null;

  const draftSummary = (draft: Draft): DraftSummary => ({
    ref: { ...draft.ref }, revision: draft.revision, updatedAt: draft.updatedAt,
    subject: draft.content.subject, to: draft.content.to, source: snapshotCopy(draft.source),
  });

  function validateDraftContent(content: DraftContent): void {
    const limits: Array<[keyof DraftContent, number]> = [['to', 16 * 1024], ['cc', 16 * 1024], ['subject', 4 * 1024], ['bodyText', 1024 * 1024]];
    for (const [field, max] of limits) {
      if (new TextEncoder().encode(content[field]).length > max) {
        throw { kind: 'invalid_request', field } satisfies MailError;
      }
    }
  }

  function draftCommandFingerprint(kind: string, command: unknown): string {
    const serialized = JSON.stringify([kind, command]);
    let first = 2166136261;
    let second = 0x9e3779b9;
    for (let i = 0; i < serialized.length; i += 1) {
      const code = serialized.charCodeAt(i);
      first = Math.imul(first ^ code, 16777619);
      second = Math.imul(second ^ (code + i), 2246822519);
    }
    return `${serialized.length}:${first >>> 0}:${second >>> 0}`;
  }

  function validateDraftRequestId(requestId: string): void {
    if (!requestId || new TextEncoder().encode(requestId).length > 128) {
      throw { kind: 'invalid_request', field: 'requestId' } satisfies MailError;
    }
  }

  function existingDraftReceipt<T extends DraftReceipt | DraftDeleteReceipt>(accountId: string, requestId: string, fingerprint: string): T | null {
    validateDraftRequestId(requestId);
    const existing = draftReceipts.get(`${accountId}:${requestId}`);
    if (!existing) return null;
    if (existing.fingerprint !== fingerprint) throw { kind: 'request_id_conflict' } satisfies MailError;
    return snapshotCopy(existing.receipt) as T;
  }

  const settle = (): Promise<void> => Promise.resolve();

  function accountStatus(): AccountStatus {
    const cached = account.mode === 'gmail'
      ? (cacheCleared ? 0 : account.cachedConversations)
      : conversations.length;
    return {
      mode: account.mode,
      connection: account.connection,
      account: account.emailAddress
        ? {
            accountId: account.mode === 'gmail' ? 'gmail-account' : fixtureId,
            emailAddress: account.emailAddress,
          }
        : null,
      sync: {
        state: account.syncState,
        lastSyncedAt: account.lastSyncedAt,
        error: account.syncError ? { ...account.syncError } : null,
        cachedConversations: cached,
        initialSyncComplete: account.initialSyncComplete,
        coverageLimit: account.coverageLimit,
      },
      mutationAccess: account.mode === 'gmail' ? account.mutationAccess : 'read_only',
    };
  }

  const byId = (conversationId: string): FakeConversation | undefined =>
    cacheCleared || !accountStatus().account ? undefined :
      conversations.find((c) => c.ref.conversationId === conversationId && c.ref.accountId === accountStatus().account?.accountId);

  const allOps = (): Array<{ conv: FakeConversation; op: InternalOperation }> =>
    conversations.flatMap((conv) => conv.ops.map((op) => ({ conv, op })));

  /** Effective prior value of the operation's dimension per target, captured before it joins the overlay. */
  function effectivePriorValues(conv: FakeConversation, kind: MailboxOperationKind, messageIds: string[]): Record<string, boolean | null> {
    const inbox = effectiveInInbox(conv);
    const read = effectiveRead(conv);
    const values: Record<string, boolean | null> = {};
    for (let i = 0; i < conv.messages.length; i += 1) {
      const message = conv.messages[i];
      if (!message || !messageIds.includes(message.id)) continue;
      // Archive ops restore archived-ness (the inverse of INBOX membership);
      // read ops restore read-ness, which can be an unknown fact.
      values[message.id] = kind === 'star' ? effectiveStars(conv)[i] ?? null : kind === 'archive' ? !inbox[i] : read[i] ?? null;
    }
    return values;
  }

  /** §3.2 rules 2–7 (rule 1 holds by construction in the single-account fake). */
  function undoBlocker(op: InternalOperation): MailError | null {
    if (op.undoOf !== undefined) return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    // Group children are part of their group's top-level action: they are never
    // individually undoable (docs/ux-05-safe-bulk-processing.md §5).
    if (op.groupId !== undefined) return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    if (Date.parse(now()) >= Date.parse(op.acceptedAt) + UNDO_WINDOW_MS) {
      return { kind: 'undo_unavailable', reason: 'expired' } satisfies MailError;
    }
    if (supersededByNewerAction(op.seq)) {
      return { kind: 'undo_unavailable', reason: 'superseded' } satisfies MailError;
    }
    if (allOps().some((entry) => entry.op.undoOf === op.id)) {
      return { kind: 'undo_unavailable', reason: 'already_undone' } satisfies MailError;
    }
    if (op.status === 'outcome_unknown') return { kind: 'undo_unavailable', reason: 'uncertain' } satisfies MailError;
    if (op.status !== 'queued' && op.status !== 'applying' && op.status !== 'confirmed') {
      // A cancelled op was already undone in place; a re-undo reports
      // already_undone, matching Rust's rule ordering.
      if (op.status === 'cancelled') return { kind: 'undo_unavailable', reason: 'already_undone' } satisfies MailError;
      return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    }
    if (op.messageIds.some((id) => op.priorValues[id] === undefined || op.priorValues[id] === null)) {
      return { kind: 'undo_unavailable', reason: 'unknown_prior' } satisfies MailError;
    }
    return null;
  }

  /** `undoableUntil` is present only while every undo rule still holds at query time. */
  function summarizeOperation(op: InternalOperation, accountId: string): OperationSummary {
    return toOperationSummary(
      op,
      accountId,
      undoBlocker(op) ? undefined : new Date(Date.parse(op.acceptedAt) + UNDO_WINDOW_MS).toISOString(),
    );
  }

  /** A newer standalone single or a newer action-bearing group supersedes `seq`. */
  function supersededByNewerAction(seq: number): boolean {
    return allOps().some((entry) => entry.op.undoOf === undefined && entry.op.groupId === undefined && entry.op.seq > seq)
      || groups.some((g) => g.acceptedChildren > 0 && g.seq > seq);
  }

  /** One group's undo window: latest top-level action, 10 s from group
   * acceptance, and at least one member still eligible (an all-ineligible
   * group offers no enabled Undo, §5). */
  function groupUndoBlocker(group: InternalGroup): MailError | null {
    if (group.undone) return { kind: 'undo_unavailable', reason: 'already_undone' } satisfies MailError;
    if (group.acceptedChildren === 0) return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    if (Date.parse(now()) >= Date.parse(group.acceptedAt) + UNDO_WINDOW_MS) {
      return { kind: 'undo_unavailable', reason: 'expired' } satisfies MailError;
    }
    if (supersededByNewerAction(group.seq)) return { kind: 'undo_unavailable', reason: 'superseded' } satisfies MailError;
    // Per-member eligibility mirrors Rust: some accepted child must be live
    // (queued/applying/confirmed), not already compensated, with known priors.
    const anyEligible = group.members.some((member) => {
      if (member.operationId === null) return false;
      const op = allOps().find((entry) => entry.op.id === member.operationId)?.op;
      if (!op) return false;
      const live = op.status === 'queued' || op.status === 'applying' || op.status === 'confirmed';
      const knownPriors = op.messageIds.every((id) => op.priorValues[id] !== undefined && op.priorValues[id] !== null);
      const notUndone = !allOps().some((entry) => entry.op.undoOf === op.id);
      return live && knownPriors && notUndone;
    });
    if (!anyEligible) return { kind: 'undo_unavailable', reason: 'not_applicable' } satisfies MailError;
    return null;
  }

  function memberStatusView(member: GroupMemberReceipt): GroupMemberStatusView {
    const op = member.operationId
      ? allOps().find((entry) => entry.op.id === member.operationId)?.op ?? null
      : null;
    return {
      ordinal: member.ordinal,
      conversation: { ...member.conversation },
      operationId: member.operationId,
      status: op ? op.status : 'rejected',
      failure: op ? op.failure : null,
      rejection: member.rejection,
    };
  }

  function groupStatus(group: InternalGroup): OperationGroupStatus {
    const blocker = groupUndoBlocker(group);
    return {
      group: snapshotCopy(groupReceipt(group)),
      members: group.members.map((member) => memberStatusView(member)),
      undo: blocker
        ? { available: false, reason: blocker.kind === 'undo_unavailable' ? blocker.reason : null, undoableUntil: null }
        : { available: true, reason: null, undoableUntil: new Date(Date.parse(group.acceptedAt) + UNDO_WINDOW_MS).toISOString() },
      ...(group.undone && group.undoReceipt ? { undoReceipt: persistedUndoRecord(group) } : {}),
    };
  }

  /** Persisted group-Undo record with CURRENT compensation outcomes (§4.2/§5);
   * mirrors Rust's `OperationGroupStatus.undoReceipt`. */
  function persistedUndoRecord(group: InternalGroup): OperationGroupStatus['undoReceipt'] {
    const receipt = group.undoReceipt;
    if (!receipt) return undefined;
    return {
      requestId: receipt.requestId,
      acceptedAt: receipt.acceptedAt,
      members: receipt.members.map((member) => ({
        ordinal: member.ordinal,
        decision: member.decision,
        compensations: member.operationIds.map((operationId) => {

      compensations: member.operationIds.map((operationId) => {
        const op = allOps().find((entry) => entry.op.id === operationId)?.op;
        return {
          operationId,
          status: op?.status ?? 'outcome_unknown',
          failure: op?.failure ?? null,
        };
      }),
    })),
  };
}

function groupReceipt(group: InternalGroup): OperationGroupReceipt {
  return {
    groupId: group.groupId,
    requestId: group.requestId,
    accountId: group.accountId,
    kind: group.kind,
    ...(group.kind === 'star' ? {requestedStarred:group.requestedArchived} : {}),
    ...(group.kind === 'star' || group.requestedArchived === undefined ? {} : { requestedArchived: group.requestedArchived }),
    ...(group.requestedRead === undefined ? {} : { requestedRead: group.requestedRead }),
    acceptedAt: group.acceptedAt,
    members: snapshotCopy(group.members),
  };
}

function groupSummary(group: InternalGroup): OperationGroupPage['groups'][number] {
  return {
    groupId: group.groupId,
    requestId: group.requestId,
    kind: group.kind,
    ...(group.kind === 'star' ? {requestedStarred:group.requestedArchived} : {}),
    ...(group.kind === 'star' || group.requestedArchived === undefined ? {} : { requestedArchived: group.requestedArchived }),
    ...(group.requestedRead === undefined ? {} : { requestedRead: group.requestedRead }),
    acceptedAt: group.acceptedAt,
    members: group.members.map((member) => ({ ...member.conversation })),
    undone: group.undone,
  };
}

/**
 * Shared group acceptance for archive and read groups (UX-05 §4.1 in-memory):
 * structural validation, idempotent receipt lookup, per-member acceptance with
 * typed rejections, one durable receipt. All-rejected valid requests still get
 * an idempotent receipt with zero child operations and consume no undo slot.
 */
function acceptGroup(
  command: { accountId: string; members: ConversationRef[]; requestId: string },
  kind: MailboxOperationKind,
  requested: { archived?: boolean; read?: boolean },
): OperationGroupReceipt {
  requireMutationAccess(kind);
  if (!command.accountId || command.accountId !== accountStatus().account?.accountId) {
    throw { kind: 'invalid_request', field: 'accountId' } satisfies MailError;
  }
  if (!Array.isArray(command.members) || command.members.length < 1 || command.members.length > OPERATION_GROUP_MAX_MEMBERS) {
    throw { kind: 'invalid_request', field: 'members' } satisfies MailError;
  }
  for (const member of command.members) {
    if (!member || typeof member.accountId !== 'string' || !member.accountId
      || typeof member.conversationId !== 'string' || !member.conversationId) {
      throw { kind: 'invalid_request', field: 'members' } satisfies MailError;
    }
  }
  // Cross-account members reject the whole request (no partial acceptance).
  if (command.members.some((member) => member.accountId !== command.accountId)) {
    throw { kind: 'invalid_request', field: 'members' } satisfies MailError;
  }
  const seen = new Set<string>();
  for (const member of command.members) {
    const key = `${member.accountId}:${member.conversationId}`;
    if (seen.has(key)) throw { kind: 'invalid_request', field: 'members' } satisfies MailError;
    seen.add(key);
  }
  const fingerprint = JSON.stringify([
    'operation-group', kind, command.accountId,
    command.members.map((member) => [member.accountId, member.conversationId]),
    requested.archived, requested.read,
  ]);
  const requestKey = `${command.accountId}:${command.requestId}`;
  const existing = groupReceiptsByRequest.get(requestKey);
  if (existing) {
    if (existing.fingerprint !== fingerprint) throw { kind: 'request_id_conflict' } satisfies MailError;
    return snapshotCopy(existing.receipt);
  }
  groupCounter += 1;
  const groupId = `grp-${String(groupCounter).padStart(4, '0')}`;
  const acceptedAt = now();
  const members: GroupMemberReceipt[] = [];
  for (let ordinal = 0; ordinal < command.members.length; ordinal += 1) {
    const ref = command.members[ordinal]!;
    const conv = byId(ref.conversationId);
    if (!conv || conv.ref.accountId !== command.accountId) {
      members.push({ ordinal, conversation: { ...ref }, operationId: null, rejection: 'conversation_missing' });
      continue;
    }
    // Mirrors core's existing 1000-messages-per-operation bound.
    if (conv.messages.length > 1000) {
      members.push({ ordinal, conversation: { ...ref }, operationId: null, rejection: 'target_bound_exceeded' });
      continue;
    }
    const child = enqueueOperation(
      conv,
      kind,
      requested.archived ?? false,
      requested.read,
      conv.messages.map((message) => message.id),
      `${command.requestId}:${ordinal}`,
      JSON.stringify(['group-child', command.requestId, ordinal]),
      { groupId, acceptedAt },
    );
    members.push({ ordinal, conversation: { accountId: ref.accountId, conversationId: ref.conversationId }, operationId: child.operationId, rejection: null });
  }
  const group: InternalGroup = {
    groupId,
    requestId: command.requestId,
    accountId: command.accountId,
    kind,
    ...(requested.archived === undefined ? {} : { requestedArchived: requested.archived }),
    ...(requested.read === undefined ? {} : { requestedRead: requested.read }),
    acceptedAt,
    seq: ++actionSeqCounter,
    members,
    acceptedChildren: members.filter((member) => member.operationId !== null).length,
    undone: false,
  };
  groups.push(group);
  const receipt = groupReceipt(group);
  groupReceiptsByRequest.set(requestKey, { fingerprint, receipt: snapshotCopy(receipt) });
  notify();
  return snapshotCopy(receipt);
}

function snapshot(): InboxSnapshot {
  reconcileFakeReminders();
  // No account / cleared cache means no cached mail; core would return the same.
  const empty =
    cacheCleared ||
    (account.mode === 'gmail' && (account.connection === 'not_configured' || account.connection === 'disconnected'));
  const activity = empty
    ? []
    : conversations
        .flatMap((c) => c.ops.map((op) => summarizeOperation(op, c.ref.accountId)))
        .sort((a, b) => a.id.localeCompare(b.id));
  const rows = empty
    ? []
    : conversations
        .map((c) => ({ c, flags: effectiveInInbox(c) }))
        .filter((entry) => !entry.c.triage && entry.flags.some((f) => f)
          && (reminders.get(`${entry.c.ref.accountId}:${entry.c.ref.conversationId}`)?.phase !== 'pending'
            || entry.c.messages.some(message => !reminderSourceInventories.get(`${entry.c.ref.accountId}:${entry.c.ref.conversationId}`)?.has(message.id))))
        .map((entry) => summarize(entry.c, pendingOperationId(entry.c)))
        .sort((a, b) => b.lastMessageAt.localeCompare(a.lastMessageAt));
  return snapshotCopy({ conversations: rows, activity });
}

function reconcileFakeReminders(): void {
  const instant = Date.parse(now());
  for (const reminder of reminders.values()) {
    if (reminder.phase === 'pending' && reminder.dueAt && Date.parse(reminder.dueAt) <= instant) {
      const conv = byId(reminder.conversation.conversationId);
      if (reminder.condition === 'if_no_reply' && (!conv || conv.contextComplete === false || conv.retainedSnapshotAt || account.connection !== 'connected' || account.syncError || !account.initialSyncComplete)) continue;
      const sourceIds = reminderSourceInventories.get(`${reminder.conversation.accountId}:${reminder.conversation.conversationId}`) ?? new Set([reminder.sourceMessageId]);
      const primary = accountStatus().account?.emailAddress?.toLowerCase();
      const replied = reminder.condition === 'if_no_reply' && conv?.messages.some(message =>
        !sourceIds.has(message.id) && message.from.mailbox.toLowerCase() !== primary);
      reminder.phase = replied ? 'suppressed' : 'returned';
      reminder.revision += 1;
    }
  }
}

function failNotShown(): MailError {
  return { kind: 'not_found' };
}

function requireMutationAccess(kind: MailboxOperationKind): void {
  if ((kind === 'read' || kind === 'star') && account.mode !== 'gmail') throw { kind: 'read_only' } satisfies MailError;
  if (account.mode === 'gmail' && account.mutationAccess !== 'enabled') throw { kind: 'read_only' } satisfies MailError;
}

function existingReceipt<T = OperationReceipt>(requestId: string, fingerprint: string): T | null {
  const existing = receiptsByRequest.get(requestId);
  if (!existing) return null;
  if (existing.fingerprint !== fingerprint) throw { kind: 'request_id_conflict' } satisfies MailError;
  return snapshotCopy(existing.receipt) as T;
}

function enqueueOperation(
  conv: FakeConversation,
  kind: MailboxOperationKind,
  requestedArchived: boolean,
  requestedRead: boolean | undefined,
  messageIds: string[],
  requestId: string,
  fingerprint: string,
  options: { priorValues?: Record<string, boolean | null>; undoOf?: string; groupId?: string; acceptedAt?: string; retryOf?: string } = {},
): OperationReceipt {
  opCounter += 1;
  const operationId = `op-${String(opCounter).padStart(4, '0')}`;
  const acceptedAt = options.acceptedAt ?? now();
  const receipt: OperationReceipt = { operationId, acceptedAt };
  receiptsByRequest.set(requestId, { fingerprint, receipt });
  const op: InternalOperation = {
    id: operationId,
    conversationId: conv.ref.conversationId,
    kind,
    requestedArchived,
    ...(requestedRead === undefined ? {} : { requestedRead }),
    messageIds: [...messageIds],
    status: 'queued',
    failure: null,
    acceptedAt,
    seq: ++actionSeqCounter,
    // Per-message effective value of THIS operation's dimension at acceptance
    // (before this op joins the overlay); retries reuse the original's preimage.
    priorValues: options.priorValues
      ? { ...options.priorValues }
      : effectivePriorValues(conv, kind, messageIds),
    ...(options.undoOf === undefined ? {} : { undoOf: options.undoOf }),
    ...(options.retryOf === undefined ? {} : { retryOf: options.retryOf }),
    ...(options.groupId === undefined ? {} : { groupId: options.groupId }),
  };
  conv.ops.push(op);
  if (behavior.hold || behavior.holdQueued) holdReleased = false;
  notify();
  void runOperation(op).then(() => notify());
  return snapshotCopy(receipt);
}

async function runOperation(op: InternalOperation): Promise<void> {
  inFlight += 1;
  try {
    // holdQueued models a worker that has not claimed the intent yet: the
    // operation stays `queued`, so undo can still cancel it in place.
    if (behavior.holdQueued && !holdReleased) {
      await new Promise<void>((resolve) => holdWaiters.push(resolve));
    }
    if (op.status === 'cancelled') return; // cancelled while still queued
    // queued -> applying (worker claims in acceptance order; fake uses FIFO)
    op.status = 'applying';
    notify();
    if (behavior.hold && !holdReleased) {
      await new Promise<void>((resolve) => holdWaiters.push(resolve));
    }
    // ArchiveProvider call happens outside any "transaction" in core; here it is
    // just an async boundary so state transitions are observable.
    await Promise.resolve();
    if (!conversations.some((conv) => conv.ops.includes(op))) return;
    if (behavior.failNext > 0) {
      behavior.failNext -= 1;
      if (behavior.failureKind === 'outcome_unknown') {
        op.status = 'outcome_unknown';
        op.lastError = { kind: 'outcome_unknown' };
      } else {
        op.status = 'failed';
        op.failure = { kind: behavior.failureKind };
        op.lastError = behavior.failureKind === 'provider_rejected'
          ? { kind: 'provider_rejected' }
          : { kind: 'provider_unavailable' };
      }
      notify();
      return;
    }
    op.failure = null;
    delete op.lastError;
    op.status = 'confirmed';
    notify();
  } finally {
    inFlight -= 1;
  }
}

